import{bV as e,aL as a,u as d,G as o}from"./chunks/framework.DvBUyM1S.js";const A=JSON.parse('{"title":"AI 网关选型对比——CLIProxyAPI vs New API vs Sub2API（含服务器开销）","description":"","frontmatter":{"id":"PB-20260907-001","type":"playbook","title":"AI 网关选型对比——CLIProxyAPI vs New API vs Sub2API（含服务器开销）","tags":["ai-gateway","cliproxyapi","new-api","sub2api"],"status":"draft","source":"web-collected:2026-09-07","created":"2026-09-07T00:00:00.000Z","updated":"2026-09-07T00:00:00.000Z"},"headers":[],"relativePath":"playbooks/ai-gateway-selection-comparison.md","filePath":"playbooks/ai-gateway-selection-comparison.md"}'),r={name:"playbooks/ai-gateway-selection-comparison.md"};function i(s,t,l,n,P,I){return a(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="ai-网关选型对比——cliproxyapi-vs-new-api-vs-sub2api-含服务器开销" tabindex="-1">AI 网关选型对比——CLIProxyAPI vs New API vs Sub2API（含服务器开销） <a class="header-anchor" href="#ai-网关选型对比——cliproxyapi-vs-new-api-vs-sub2api-含服务器开销" aria-label="Permalink to &quot;AI 网关选型对比——CLIProxyAPI vs New API vs Sub2API（含服务器开销）&quot;">​</a></h1><p>一句话：三者都把上游 AI 能力统一暴露成 API，但层级不同—— CLIProxyAPI 是<strong>协议桥接器</strong>（接入层）、New API 是<strong>网关治理平台</strong>（管理层）、Sub2API 是<strong>订阅分发运营平台</strong>（运营层）。</p><h2 id="结论速查-按服务器开销排序" tabindex="-1">结论速查（按服务器开销排序） <a class="header-anchor" href="#结论速查-按服务器开销排序" aria-label="Permalink to &quot;结论速查（按服务器开销排序）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>CLIProxyAPI</th><th>New API</th><th>Sub2API</th></tr></thead><tbody><tr><td>定位</td><td>CLI/OAuth 订阅 → 标准 API 桥接</td><td>多供应商渠道聚合 + 令牌/计费治理</td><td>订阅配额池化、Key 分发、并发限流、内置支付</td></tr><tr><td>依赖</td><td>无（单二进制 + 配置热更新）</td><td>SQLite 起步，可选 MySQL/PG + Redis</td><td><strong>强制 PostgreSQL 15+ 与 Redis 7+</strong></td></tr><tr><td>资源占用</td><td>最低：程序 ~10MB、内存 &lt;10~50MB</td><td>低：1C1G 可跑</td><td>高：Go + PG + Redis 三件套；1C1G 实测首字响应 3 分钟，建议 2C2G+</td></tr><tr><td>上游</td><td>Gemini CLI / Codex / Claude Code / Qwen 等 CLI/OAuth 账号</td><td>OpenAI / Claude / Azure 等标准 API</td><td>Claude / OpenAI / Gemini 等订阅账号池</td></tr><tr><td>运维故障面</td><td>OAuth 过期、CLI 协议变动（风险在上游）</td><td>规模化后渠道/计费治理</td><td>环境变量 + DB/Redis 配置敏感（Nginx 需 <code>underscores_in_headers on;</code> 否则粘性会话失效）</td></tr></tbody></table><h2 id="选型" tabindex="-1">选型 <a class="header-anchor" href="#选型" aria-label="Permalink to &quot;选型&quot;">​</a></h2><ol><li><strong>自用 / 个人开发者</strong>：CLIProxyAPI——最小开销，小水管 VPS 可跑。</li><li><strong>团队统一网关（计费/权限/多渠道）</strong>：New API——SQLite 起步最省心。</li><li><strong>多人分发 Key / 拼车运营</strong>：Sub2API——功能最全（Token 级计费、用户/账号级并发、EasyPay/支付宝/Stripe），但服务器预算给足。</li><li>分层组合（接入→治理→运营）只在三层能力都真需要时上，复杂度显著上升。</li></ol><h2 id="服务器配置建议-2026-09-07-补充" tabindex="-1">服务器配置建议（2026-09-07 补充） <a class="header-anchor" href="#服务器配置建议-2026-09-07-补充" aria-label="Permalink to &quot;服务器配置建议（2026-09-07 补充）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>工具</th><th>最低</th><th>流畅</th><th>备注</th></tr></thead><tbody><tr><td>CLIProxyAPI</td><td>1C 512MB / 5G 盘</td><td>1C 1G</td><td>内存 &lt;50MB，1 核可扛几十路流式并发</td></tr><tr><td>New API</td><td>1C 1G / 10G 盘（SQLite）</td><td>2C 2G（百人级 + MySQL/PG/Redis）</td><td>Go 单进程 ~100-200MB</td></tr><tr><td>Sub2API</td><td><strong>2C 2G</strong> / 20G 盘</td><td>2C 4G（100+ 用户再 4C）</td><td>1C1G 实测不可用（首字 3 分钟）；三件套常驻 800MB-1G</td></tr></tbody></table><ul><li>小内存机器加 1-2G swap：PG 被 OOM 是 Sub2API 常见故障。</li><li>磁盘必须 SSD/NVMe：网关高频小写入（日志/计费流水），机械盘拖垮 PG。</li><li>带宽 ≥5Mbps：流式输出是长连接持续流量；国内访问 Claude/OpenAI 的首字延迟大头在出海线路，不在机器配置。</li><li>并发估算：每路流式对话 10-50MB 内存，2C2G 稳 20-50 并发。</li></ul><h2 id="备注" tabindex="-1">备注 <a class="header-anchor" href="#备注" aria-label="Permalink to &quot;备注&quot;">​</a></h2><ul><li>Sub2API 有 <code>RUN_MODE=simple</code> 简易模式：隐藏 SaaS 功能、跳过计费，个人/内部团队可减负。</li><li>合规：CLIProxyAPI / Sub2API 涉及订阅共享，可能违反上游服务条款（封号风险）；New API 接标准 API 渠道相对可控。</li><li>来源：CSDN 对比文（2026-07）、51CTO 对比文（2026-04）、Sub2API 官方 README_CN、zhihu 实测帖（2026-03）、lusipad CLIProxyAPI 教程（v6）。</li></ul>',11)])])}const u=e(r,[["render",i]]);export{A as __pageData,u as default};
